UPDATE sn_factory SET cfg_tested = #{tested}, cfg_checked_at = #{now}, cfg_message = #{message},
  cfg_status = #{status}
WHERE factory_code = #{code}

UPDATE sn_factory SET mes_url = #{entity.mesUrl}, mes_auth_type = #{entity.mesAuthType},
  mes_credential = #{entity.mesCredential}, mes_gzip = #{entity.mesGzip}, batch_size = #{entity.batchSize},
  push_timeout_sec = #{entity.pushTimeoutSec}, push_concurrency = #{entity.pushConcurrency},
  tz_offset_min = #{entity.tzOffsetMin}, cfg_status = #{entity.cfgStatus}, updated_at = #{entity.updatedAt}
WHERE factory_code = #{entity.factoryCode}
